# Define the helper functions that were mentioned in the prompt
def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple approach: find first differing position
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or replacing
            if len(s_in) > len(s_out):
                # Removing character at position i
                return (s_in[i], "", i)
            elif len(s_in) < len(s_out):
                # Adding character at position i  
                return ("", s_out[i], i)
            else:
                # Replacing character at position i
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) > len(s_out):
        return (s_in[min_len], "", min_len)
    elif len(s_in) < len(s_out):
        return ("", s_out[min_len], min_len)
    else:
        return ("", "", -1)  # No difference

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair."""
    # Find minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return most specific rule first, then more general ones
    candidates = []

    # Specific case: exact substring match
    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))
    elif old_sub and not new_sub:
        candidates.append((old_sub, ""))
    elif not old_sub and new_sub:
        candidates.append(("", new_sub))

    # General cases - try to match larger substrings if possible
    if len(s_in) >= 2 and len(s_out) >= 2:
        # Try matching 2-character patterns
        if len(s_in) >= 2 and len(s_out) >= 2:
            candidates.append((s_in[:2], s_out[:2]))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on inputs/outputs."""
    results = apply_rules(inputs, rules)
    correct = sum(1 for r, o in zip(results, outputs) if r == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find inputs that are incorrectly modified by rules."""
    results = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, result) in enumerate(zip(inputs, outputs, results)):
        if result != outp:
            over_apps.append((i, inp, result))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Create proxy rules to prevent counterfeeding."""
    pre_rule = (pattern, proxy)
    post_rule = (proxy, replacement)
    return (pre_rule, post_rule)

# Now let's use these functions
inputs = ['ijxfu', 'ybe', 'euba', 'bhw', 'zzedd']
outputs = ['ijcuueeju', 'ykxge', 'eukxgkxgwc', 'kxghw', 'zzedd']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, s_in, s_out in changed:
    print(f"  {idx}: '{s_in}' -> '{s_out}'")

